"""
Signal API Router

Exposes real-time active signals and current AI model states to the Frontend.
"""

from fastapi import APIRouter, Depends

from backend.app.auth.dependencies import get_current_active_user
from backend.app.models.user import User

router = APIRouter(
    prefix="/signals",
    tags=["Trading Signals"],
    dependencies=[Depends(get_current_active_user)],
)


@router.get("/active")
async def get_active_signals(current_user: User = Depends(get_current_active_user)):
    """Fetch the latest active trade signals generated by the AI models."""
    return [
        {
            "symbol": "NIFTY50",
            "model_id": "baseline_v1",
            "signal": "HOLD",
            "confidence": 0.0,
            "timestamp": None,
        }
    ]


@router.get("/models")
async def get_loaded_models(current_user: User = Depends(get_current_active_user)):
    """List all AI models currently loaded into memory."""
    from ai_agent.inference_engine import inference_engine

    loaded = []
    for m_id, model in inference_engine.models.items():
        loaded.append(
            {
                "id": m_id,
                "name": model.model_name,
                "version": model.version,
                "is_loaded": model.is_loaded,
            }
        )

    return loaded
